	for s in problems:
		print("PROBLEM " + s)
	print("LAND PREVIEW: trigger_frame=%d touchdown_tick=%d problems=%d" % [trigger_frame, touchdown_tick, problems.size()])
	set_process(false)
	hook.set_physics_process(false)
	get_tree().quit(1 if problems.size() > 0 else 0)

